class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        if (n < 2) return s;
        string best = s.substr(0, 1);
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                int l = i, r = j;
                bool ok = true;
                while (l < r) {
                    if (s[l++] != s[r--]) { ok = false; break; }
                }
                if (ok && j - i + 1 > (int)best.size())
                    best = s.substr(i, j - i + 1);
            }
        }
        return best;
    }
};

