    def longestPalindrome(self, s: str) -> str:
        if len(s) < 2:
            return s
        t = '^#' + '#'.join(s) + '#$'
        n = len(t)
        p = [0]*n
        c = r = 0
        for i in range(1, n-1):
            mir = 2*c - i
            if i < r:
                p[i] = min(r - i, p[mir])
            while t[i+1+p[i]] == t[i-1-p[i]]:
                p[i] += 1
            if i + p[i] > r:
                c, r = i, i + p[i]
        maxLen = max(p)
        center = p.index(maxLen)
        start = (center - maxLen)//2
        return s[start:start+maxLen]

